// File manually maintained - not generated by Stainless

package blaxel

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
)

// maxStreamLineBytes caps one line of a streamed response. It sits far above
// the longest line the sandbox API sends today (the final result event of a
// streamed exec, which repeats the output the API kept, JSON-escaped twice)
// and above its larger planned output limits, so it only stops a runaway
// stream from using unbounded memory.
const maxStreamLineBytes = 256 << 20

// streamLineScanner reads the lines of a streamed response body. It replaces
// bufio.Scanner, whose default 64 KB line limit made ExecWithStreaming fail
// once a command printed about 32 KB, and which rescans the whole line on
// every read, so long lines cost quadratic time. Lines can be any length up
// to maxStreamLineBytes, and reading them is linear.
type streamLineScanner struct {
	r    *bufio.Reader
	max  int
	line []byte
	err  error
}

func newStreamLineScanner(r io.Reader) *streamLineScanner {
	return &streamLineScanner{r: bufio.NewReaderSize(r, 64<<10), max: maxStreamLineBytes}
}

// Scan reads the next line, which Bytes and Text then return without its
// trailing "\n" or "\r\n". A last line with no newline is returned too. Scan
// returns false at the end of the stream or on an error; Err returns the
// error, or nil at a clean end.
func (s *streamLineScanner) Scan() bool {
	if s.err != nil {
		return false
	}
	s.line = s.line[:0]
	for {
		chunk, err := s.r.ReadSlice('\n')
		if len(s.line)+len(chunk) > s.max {
			s.err = fmt.Errorf("stream line longer than %d bytes", s.max)
			return false
		}
		s.line = append(s.line, chunk...)
		switch {
		case err == nil:
			s.line = bytes.TrimSuffix(s.line[:len(s.line)-1], []byte("\r"))
			return true
		case errors.Is(err, bufio.ErrBufferFull):
			continue
		case errors.Is(err, io.EOF):
			if len(s.line) == 0 {
				return false
			}
			s.line = bytes.TrimSuffix(s.line, []byte("\r"))
			return true
		default:
			s.err = err
			return false
		}
	}
}

// Bytes returns the line read by the last Scan. The next Scan overwrites it.
func (s *streamLineScanner) Bytes() []byte { return s.line }

// Text returns the line read by the last Scan as a string.
func (s *streamLineScanner) Text() string { return string(s.line) }

// Err returns the error that stopped Scan, or nil at a clean end of stream.
func (s *streamLineScanner) Err() error { return s.err }
